INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Millennium Runners', 'The ultimate anti-gravity racing experience. Millennium Runners is an homage to classic arcade racing games. Speed through futuristic cities and planets in adrenaline-fueled competitions. Along the way, you''ll discover hidden easter eggs and pick up an arsenal of power-ups — from rockets to mines and more — designed either to propel you to victory or to hinder your rivals. Choose your team, conquer the Millennium Cup, and race your way into legend!' FROM games WHERE igdb_id = 336121 ON CONFLICT (game_id, language_code) DO NOTHING;
