INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jǐn Nǐ Yī Rén', 'I was known as the "problem girl," and she was the center of the class. Two seemingly unconnected lines, however, collided through a series of coincidences, shattering my bleak life. I wanted to monopolize her gaze, to be the only one by her side. Starting with that encounter in the hills behind the school, the pure longing in my heart gradually began to distort.' FROM games WHERE igdb_id = 373712 ON CONFLICT (game_id, language_code) DO NOTHING;
