INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kakegurui All In', 'Kakegurui ALL IN is a browser-based strategy board game based on the Kakegurui anime television series. Players roll dice to advance across stages in a board-game format, with the goal of progressing through increasingly challenging levels. Gameplay centers on collecting characters and items drawn from the Kakegurui franchise, which can be equipped to provide strategic advantages during play. As the player builds their collection, they gain access to stronger combinations that influence the outcome of each stage. The game runs entirely in a web browser and requires no account registration or software download to play.' FROM games WHERE igdb_id = 395906 ON CONFLICT (game_id, language_code) DO NOTHING;
