INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Veredilia: The Sacred Forest', 'Veredilia: The Sacred Forest is a 2D platforming game that takes inspiration from classic platformers such as Sonic, and fighting games like Mortal Kombat. The game aims to be a combination of classic 2D platforming with 1v1 fighting whilst also exploring the large forest of Veredilia across various locales with a wide range of characters, technical movesets, and flashy combos. You can take control of one of 3 characters, each with their own special moves, combos, and super moves. Solve puzzles, uncover secrets, and kick, punch, and slash your way to victory, before it''s too late. Do you have what it takes?' FROM games WHERE igdb_id = 265932 ON CONFLICT (game_id, language_code) DO NOTHING;
