INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grapple Souls', 'I wanted to see if I could capture the deliberate, punishing combat that makes these games work. This isn''t a sprawling 100 hour RPG. It''s a small, focused slice of a world that doesn''t care if you live or die. If you miss slowly opening doors like an anime character, you''ll love this.' FROM games WHERE igdb_id = 388333 ON CONFLICT (game_id, language_code) DO NOTHING;
