INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Survivesmith', 'Reverse bullet-hell game with a crafting twist. Shoot hails of bullets, missiles, nails, lasers and whatever is at your disposal at your enemies and make tactical choices to overcome all obstacles. You are here to find and extract the ''Life Essence'', and you''re not leaving without it!' FROM games WHERE igdb_id = 346628 ON CONFLICT (game_id, language_code) DO NOTHING;
