INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcabbit', 'Latch on with two hooks and ride the momentum of a pendulum swing. Swap left and right in rhythm to blaze through neon stages in this 2D action game. Stage mechanics sync with the soundtrack for a snappy “one more try” loop.' FROM games WHERE igdb_id = 363172 ON CONFLICT (game_id, language_code) DO NOTHING;
