INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Z Route: Redemption', 'Post apocalyptic zombie action game that throws you into a relentless road war, where survival hinges on speed, precision, and split second decisions. Behind the wheel, you smash through barricades, mow down swarms, and pick between branching gates that hide supply caches or deadly ambushes. Each run pushes you forward toward redemption as you tune weapons, react to hazards, and keep momentum alive to outpace the horde.' FROM games WHERE igdb_id = 395510 ON CONFLICT (game_id, language_code) DO NOTHING;
