INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberball', 'Bomberball is a sci-fi multiplayer sports-shooter hybrid with class-based loadouts. Run, pass, and throw a planet-killer bomb into the opposing team’s rift. Fight in tightly-crafted arenas, and coordinate formations with your teammates. Experience the fast-paced, strategic combat of the future.' FROM games WHERE igdb_id = 392144 ON CONFLICT (game_id, language_code) DO NOTHING;
