INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I''ve Been Holding My Breath Since 2008', 'After moving back to your parents'' house, you find a box labeled 2008. Inside is a relic you thought was dead: an old slider phone. Surprisingly, it flickers to life, revealing a digital graveyard of who you used to be at eleven — an outsider, an artist, and a girl who was terrified of being seen.' FROM games WHERE igdb_id = 385031 ON CONFLICT (game_id, language_code) DO NOTHING;
