INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glint''s Revenge', 'Glint’s Revenge is a retro platformer with a bold black-and-white aesthetic, where you play as Glint, an alien armed with a blaster on a quest through 10 deadly levels packed with traps, enemies, and clever puzzles. Shoot your way past relentless foes, flip levers to unlock hidden paths, and survive a gauntlet of challenges that demand quick reflexes and sharp thinking, all wrapped in a minimalist style that makes every move and every mistake stand out. A game developed by CraePlay and ported by GGmuks.' FROM games WHERE igdb_id = 390319 ON CONFLICT (game_id, language_code) DO NOTHING;
