INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hentai Tales: The Red Act In Lockdown', 'My world is a cramped apartment in Isolation Zone 704. Ever since the "Red Act" was enforced, nights have become a deadly game. The “Sows”—terrifying creatures that drain men—lurk in the darkness. But when a knock echoes at my door, hunger and loneliness tempt me to gamble with my life.' FROM games WHERE igdb_id = 389604 ON CONFLICT (game_id, language_code) DO NOTHING;
