INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teeko', 'Platformer meets tower defense in this story-rich game inspired by the Costa Rican Día de Las Mascaradas festival. One day, grandma Tita''s kids get possessed by the spirits of the gigantes and begin to wreak havoc upon the land. It''s now up to her pet sloth, Teeko, to save their town.' FROM games WHERE igdb_id = 347844 ON CONFLICT (game_id, language_code) DO NOTHING;
