INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scraps of the Machine', 'FPS Mech Action! Pilot a mass of steel through a single player campaign set in a desolate landscape. Target enemy armor or weapons to wear them down piece by piece, find upgrades to improve your mech or change its loadout, and survive in a world of rust and decay. Discover, Destroy, Scavenge.' FROM games WHERE igdb_id = 377683 ON CONFLICT (game_id, language_code) DO NOTHING;
