INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Troll Chess Sekai', 'One day, you gain the power to cast a troll spell in a chess game. Eager to try it out, you head to the chess club—where rivals range from novice Mirai to the mysterious owner who surpasses human skill. The rules of chess are no longer safe. Will you seize victory, or be swallowed by chaos?' FROM games WHERE igdb_id = 371162 ON CONFLICT (game_id, language_code) DO NOTHING;
