INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HexBreakerII', 'A supernatural game infused with Chinese-style elements drawn from folklore. This game offers online gameplay for teams of up to 4 players. In a world ravaged by warlords and monsters, you will assume the role of a Taoist, wielding your skills to unveil truths hidden for millennia.' FROM games WHERE igdb_id = 392056 ON CONFLICT (game_id, language_code) DO NOTHING;
