INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Food Truck Chef: Full Course Edition', 'In Food Truck Chef: Full Course Edition, you explore vibrant locations and unlock fresh levels, each introducing a brand-new lineup of special dishes to perfect. Packed with delicious recipes from around the world, this is a true culinary journey. From the lively sights of Oriental Street and the smoky goodness of BBQ Street to the sugary treats of Donut and Waffle Street, tackle every challenge and complete each cooking mission. Simple to pick up but tough to perfect, this high-speed cooking game features some mechanics that keep you on your toes.' FROM games WHERE igdb_id = 386673 ON CONFLICT (game_id, language_code) DO NOTHING;
