INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peak Rhythm', 'Ascend to the beat in Peak Rhythm! In this VR rhythm-climbing game, every grab and twist drives your robotic platform upward through a neon-soaked city. Sync your moves to a high-octane electronic soundtrack to master the flow and dominate global leaderboards. Blending physical precision with Cyberpunk aesthetics, your rhythm is your engine. Don’t just climb—perform.' FROM games WHERE igdb_id = 393870 ON CONFLICT (game_id, language_code) DO NOTHING;
