INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puffin Parcel Post', 'Puffin Parcel Post is a charming roguelite strategy game where players build and manage postal networks using adorable puffin workers. The game combines base-building mechanics with logistics optimization and strategic placement of buildings. Each playthrough offers fresh challenges through unlockable perks and upgrades that change how you approach building your postal empire. Players construct delivery routes, manage resources, and watch their cute puffin team waddle and zip across the map delivering parcels.' FROM games WHERE igdb_id = 346106 ON CONFLICT (game_id, language_code) DO NOTHING;
