INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BroomSweeper', 'BroomSweeper is a Minesweeper-style Roguelike puzzle game. Unmask the evil lurking at TentaTech, Inc. as you ascend through increasingly challenging floors. Assemble winning combinations from over 100 powerful items to defeat the dust bunnies and keep your job until morning!' FROM games WHERE igdb_id = 345662 ON CONFLICT (game_id, language_code) DO NOTHING;
