INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chop Shop', 'Feel the flow as you hunt, butcher, and cook at a blisteringly fast pace in this action shop-keeping game. Hunt adorable monsters, chop colossal carcasses, and power-slice through huge chunks of flesh to serve your customers even faster. Move fast and stay sharp if you want your shop to survive.' FROM games WHERE igdb_id = 324659 ON CONFLICT (game_id, language_code) DO NOTHING;
