INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rescue Heli RH407', 'An arcade game with a retro vibe. Navigate a helicopter in 2.5D and rescue people waiting for transport. Don''t overdo the aerial acrobatics -passengers might fall out! Land softly! And be quick -you''re running out of fuel. The physical simulation of flight adds a modern twist to the retro gameplay.' FROM games WHERE igdb_id = 345006 ON CONFLICT (game_id, language_code) DO NOTHING;
