INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Striatum', 'A quickplay and replayable first-person point-and-click adventure with a low-poly 3D retro style about getting ready for a party, featuring branching story paths with multiple in-game characters, 100+ items to discover and collect, and many interactions and events.' FROM games WHERE igdb_id = 342647 ON CONFLICT (game_id, language_code) DO NOTHING;
