INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dinosaur Survival Simulator: Prehistoric RPG', 'Step into a world ruled by teeth, claws, and raw survival. Start as a small, fragile dinosaur and fight your way through life—hunting, hiding, and adapting in a prehistoric wilderness where danger lurks behind every rock and in every shadow. Grow stronger, dominate territories, and unlock more powerful dinosaurs as you rise through life stages, shaping your destiny in a world where only the clever and ruthless survive.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 387179 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
