INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Town of Nowhere: End Of The Line', 'This is the first downloadable entry in the Town of Nowhere series. This game was made with the intention of being playable and enjoyable regardless of if you know the back story of the larger surrealist horror series. Largely inspired by CGA DOS adventure games TTON:EotL is in full first person 3D.' FROM games WHERE igdb_id = 383448 ON CONFLICT (game_id, language_code) DO NOTHING;
