INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('running-horror', 386813, '2026-01-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobc9w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar55d9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Running Horror', 'A first-person horror game where you must explore a vast labyrinth, evade a relentless demonic Beast, and find trapped survivors to reverse a miscast spell and escape.' FROM games WHERE igdb_id = 386813 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 386813 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
